words.display:
SELECT Id, ROW_NUMBER() OVER (
  ORDER BY CreatedAt, Id
) AS RowNo FROM dbo.Users;

SELECT Id, UserId, Amount, SUM(Amount) OVER (
  PARTITION BY UserId
) AS Total
FROM dbo.Orders;

SELECT Id, LAG(Amount) OVER (
  PARTITION BY UserId
  ORDER BY Id
) AS Previous
FROM dbo.Orders;

DECLARE @i int = 0;
WHILE @i < 3
BEGIN
  IF @i = 1 PRINT N'one';
  SET @i += 1;
END;
